class Solution {
    fun twoSum(nums: IntArray, target: Int): IntArray {
        val seen = HashMap<Int, Int>()
        for ((i, num) in nums.withIndex()) {
            seen[target - num]?.let { return intArrayOf(it, i) }
            seen[num] = i
        }
        return intArrayOf()
    }
}

class Solution {
    fun containsDuplicate(nums: IntArray): Boolean {
        val seen = HashSet<Int>()
        for (num in nums) {
            if (!seen.add(num)) return true
        }
        return false
    }
}

class Solution {
    fun groupAnagrams(strs: Array<String>): List<List<String>> {
        val groups = HashMap<String, MutableList<String>>()
        for (s in strs) {
            val count = IntArray(26)
            for (c in s) count[c - 'a']++
            groups.getOrPut(count.joinToString("#")) { mutableListOf() }.add(s)
        }
        return groups.values.toList()
    }
}

class Solution {
    fun isAnagram(s: String, t: String): Boolean {
        if (s.length != t.length) return false
        val count = IntArray(26)
        for (i in s.indices) {
            count[s[i] - 'a']++
            count[t[i] - 'a']--
        }
        return count.all { it == 0 }
    }
}

class Solution {
    fun topKFrequent(nums: IntArray, k: Int): IntArray {
        val freq = HashMap<Int, Int>()
        for (n in nums) freq[n] = (freq[n] ?: 0) + 1
        val buckets = Array(nums.size + 1) { mutableListOf<Int>() }
        for ((num, f) in freq) buckets[f].add(num)
        val result = IntArray(k)
        var idx = 0
        for (f in nums.size downTo 1) {
            for (num in buckets[f]) {
                if (idx == k) return result
                result[idx++] = num
            }
        }
        return result
    }
}

class Solution {
    fun productExceptSelf(nums: IntArray): IntArray {
        val n = nums.size
        val result = IntArray(n)
        result[0] = 1
        for (i in 1 until n) result[i] = result[i - 1] * nums[i - 1]
        var suffix = 1
        for (i in n - 1 downTo 0) {
            result[i] *= suffix
            suffix *= nums[i]
        }
        return result
    }
}

class Solution {
    fun maxProfit(prices: IntArray): Int {
        var minPrice = Int.MAX_VALUE
        var best = 0
        for (p in prices) {
            if (p < minPrice) minPrice = p
            else if (p - minPrice > best) best = p - minPrice
        }
        return best
    }
}

class Solution {
    fun longestConsecutive(nums: IntArray): Int {
        val set = nums.toHashSet()
        var best = 0
        for (num in set) {
            if (num - 1 in set) continue
            var len = 1
            while (num + len in set) len++
            if (len > best) best = len
        }
        return best
    }
}

class Solution {
    fun isValidSudoku(board: Array<CharArray>): Boolean {
        val rows = Array(9) { BooleanArray(9) }
        val cols = Array(9) { BooleanArray(9) }
        val boxes = Array(9) { BooleanArray(9) }
        for (r in 0 until 9) {
            for (c in 0 until 9) {
                val ch = board[r][c]
                if (ch == '.') continue
                val d = ch - '1'
                val b = (r / 3) * 3 + c / 3
                if (rows[r][d] || cols[c][d] || boxes[b][d]) return false
                rows[r][d] = true
                cols[c][d] = true
                boxes[b][d] = true
            }
        }
        return true
    }
}

class NumArray(nums: IntArray) {
    private val prefix = IntArray(nums.size + 1)

    init {
        for (i in nums.indices) prefix[i + 1] = prefix[i] + nums[i]
    }

    fun sumRange(left: Int, right: Int): Int = prefix[right + 1] - prefix[left]
}

class Solution {
    fun subarraySum(nums: IntArray, k: Int): Int {
        val count = HashMap<Int, Int>()
        count[0] = 1
        var sum = 0
        var result = 0
        for (n in nums) {
            sum += n
            result += count[sum - k] ?: 0
            count[sum] = (count[sum] ?: 0) + 1
        }
        return result
    }
}

class Solution {
    fun checkSubarraySum(nums: IntArray, k: Int): Boolean {
        val firstIndex = HashMap<Int, Int>()
        firstIndex[0] = -1
        var rem = 0
        for (i in nums.indices) {
            rem = (rem + nums[i]) % k
            val prev = firstIndex[rem]
            if (prev == null) firstIndex[rem] = i
            else if (i - prev >= 2) return true
        }
        return false
    }
}

class Solution {
    fun majorityElement(nums: IntArray): Int {
        var candidate = 0
        var count = 0
        for (n in nums) {
            if (count == 0) candidate = n
            count += if (n == candidate) 1 else -1
        }
        return candidate
    }
}

class Solution {
    fun sortColors(nums: IntArray) {
        var low = 0
        var mid = 0
        var high = nums.size - 1
        while (mid <= high) {
            when (nums[mid]) {
                0 -> { swap(nums, low++, mid++) }
                2 -> { swap(nums, mid, high--) }
                else -> mid++
            }
        }
    }

    private fun swap(a: IntArray, i: Int, j: Int) {
        val t = a[i]; a[i] = a[j]; a[j] = t
    }
}

class Solution {
    fun maxSubArray(nums: IntArray): Int {
        var current = nums[0]
        var best = nums[0]
        for (i in 1 until nums.size) {
            current = maxOf(nums[i], current + nums[i])
            best = maxOf(best, current)
        }
        return best
    }
}

class Solution {
    fun merge(nums1: IntArray, m: Int, nums2: IntArray, n: Int) {
        var i = m - 1
        var j = n - 1
        var k = m + n - 1
        while (j >= 0) {
            if (i >= 0 && nums1[i] > nums2[j]) nums1[k--] = nums1[i--]
            else nums1[k--] = nums2[j--]
        }
    }
}

class Solution {
    fun rotate(nums: IntArray, k: Int) {
        val n = nums.size
        val r = k % n
        reverse(nums, 0, n - 1)
        reverse(nums, 0, r - 1)
        reverse(nums, r, n - 1)
    }

    private fun reverse(a: IntArray, from: Int, to: Int) {
        var l = from
        var h = to
        while (l < h) {
            val t = a[l]; a[l] = a[h]; a[h] = t
            l++; h--
        }
    }
}

class Solution {
    fun firstMissingPositive(nums: IntArray): Int {
        val n = nums.size
        for (i in 0 until n) {
            while (nums[i] in 1..n && nums[nums[i] - 1] != nums[i]) {
                val j = nums[i] - 1
                val t = nums[i]; nums[i] = nums[j]; nums[j] = t
            }
        }
        for (i in 0 until n) if (nums[i] != i + 1) return i + 1
        return n + 1
    }
}

class Solution {
    fun findDisappearedNumbers(nums: IntArray): List<Int> {
        for (v in nums) {
            val idx = Math.abs(v) - 1
            if (nums[idx] > 0) nums[idx] = -nums[idx]
        }
        val result = mutableListOf<Int>()
        for (i in nums.indices) if (nums[i] > 0) result.add(i + 1)
        return result
    }
}

class Solution {
    fun spiralOrder(matrix: Array<IntArray>): List<Int> {
        val res = mutableListOf<Int>()
        var top = 0
        var bottom = matrix.size - 1
        var left = 0
        var right = matrix[0].size - 1
        while (top <= bottom && left <= right) {
            for (c in left..right) res.add(matrix[top][c])
            top++
            for (r in top..bottom) res.add(matrix[r][right])
            right--
            if (top <= bottom) {
                for (c in right downTo left) res.add(matrix[bottom][c])
                bottom--
            }
            if (left <= right) {
                for (r in bottom downTo top) res.add(matrix[r][left])
                left++
            }
        }
        return res
    }
}

class Solution {
    fun rotate(matrix: Array<IntArray>) {
        val n = matrix.size
        for (i in 0 until n) {
            for (j in i + 1 until n) {
                val t = matrix[i][j]; matrix[i][j] = matrix[j][i]; matrix[j][i] = t
            }
        }
        for (row in matrix) row.reverse()
    }
}

class Solution {
    fun isPalindrome(s: String): Boolean {
        var l = 0
        var r = s.length - 1
        while (l < r) {
            while (l < r && !s[l].isLetterOrDigit()) l++
            while (l < r && !s[r].isLetterOrDigit()) r--
            if (s[l].lowercaseChar() != s[r].lowercaseChar()) return false
            l++; r--
        }
        return true
    }
}

class Solution {
    fun twoSum(numbers: IntArray, target: Int): IntArray {
        var l = 0
        var r = numbers.size - 1
        while (l < r) {
            val sum = numbers[l] + numbers[r]
            when {
                sum == target -> return intArrayOf(l + 1, r + 1)
                sum < target -> l++
                else -> r--
            }
        }
        return intArrayOf()
    }
}

class Solution {
    fun threeSum(nums: IntArray): List<List<Int>> {
        nums.sort()
        val res = mutableListOf<List<Int>>()
        for (i in 0 until nums.size - 2) {
            if (nums[i] > 0) break
            if (i > 0 && nums[i] == nums[i - 1]) continue
            var l = i + 1
            var r = nums.size - 1
            while (l < r) {
                val sum = nums[i] + nums[l] + nums[r]
                when {
                    sum < 0 -> l++
                    sum > 0 -> r--
                    else -> {
                        res.add(listOf(nums[i], nums[l], nums[r]))
                        while (l < r && nums[l] == nums[l + 1]) l++
                        while (l < r && nums[r] == nums[r - 1]) r--
                        l++; r--
                    }
                }
            }
        }
        return res
    }
}

class Solution {
    fun moveZeroes(nums: IntArray) {
        var write = 0
        for (i in nums.indices) {
            if (nums[i] != 0) {
                val tmp = nums[write]
                nums[write] = nums[i]
                nums[i] = tmp
                write++
            }
        }
    }
}

class Solution {
    fun maxArea(height: IntArray): Int {
        var l = 0
        var r = height.size - 1
        var best = 0
        while (l < r) {
            best = maxOf(best, minOf(height[l], height[r]) * (r - l))
            if (height[l] < height[r]) l++ else r--
        }
        return best
    }
}

class Solution {
    fun trap(height: IntArray): Int {
        var l = 0
        var r = height.size - 1
        var leftMax = 0
        var rightMax = 0
        var water = 0
        while (l < r) {
            if (height[l] < height[r]) {
                leftMax = maxOf(leftMax, height[l])
                water += leftMax - height[l]
                l++
            } else {
                rightMax = maxOf(rightMax, height[r])
                water += rightMax - height[r]
                r--
            }
        }
        return water
    }
}

class Solution {
    fun removeDuplicates(nums: IntArray): Int {
        if (nums.isEmpty()) return 0
        var k = 1
        for (i in 1 until nums.size) {
            if (nums[i] != nums[k - 1]) {
                nums[k++] = nums[i]
            }
        }
        return k
    }
}

class Solution {
    fun threeSumClosest(nums: IntArray, target: Int): Int {
        nums.sort()
        var best = nums[0] + nums[1] + nums[2]
        for (i in 0 until nums.size - 2) {
            if (i > 0 && nums[i] == nums[i - 1]) continue
            var lo = i + 1
            var hi = nums.size - 1
            while (lo < hi) {
                val sum = nums[i] + nums[lo] + nums[hi]
                if (Math.abs(sum - target) < Math.abs(best - target)) best = sum
                when {
                    sum < target -> lo++
                    sum > target -> hi--
                    else -> return sum
                }
            }
        }
        return best
    }
}

class Solution {
    fun fourSum(nums: IntArray, target: Int): List<List<Int>> {
        nums.sort()
        val n = nums.size
        val result = mutableListOf<List<Int>>()
        for (i in 0 until n - 3) {
            if (i > 0 && nums[i] == nums[i - 1]) continue
            for (j in i + 1 until n - 2) {
                if (j > i + 1 && nums[j] == nums[j - 1]) continue
                var lo = j + 1
                var hi = n - 1
                while (lo < hi) {
                    val sum = nums[i].toLong() + nums[j] + nums[lo] + nums[hi]
                    when {
                        sum < target -> lo++
                        sum > target -> hi--
                        else -> {
                            result.add(listOf(nums[i], nums[j], nums[lo], nums[hi]))
                            lo++
                            hi--
                            while (lo < hi && nums[lo] == nums[lo - 1]) lo++
                            while (lo < hi && nums[hi] == nums[hi + 1]) hi--
                        }
                    }
                }
            }
        }
        return result
    }
}
